/**
 * The shape and weight math every CIO glyph shares.
 *
 * A glyph is drawn in a 24 box and grouped with a fit transform that scales its
 * own drawing up to that box, which is how one set reads at 12, 16 and 20px
 * without redrawing. The transform scales the stroke with the geometry, so a
 * group divides the weight it wants by its own scale to land on it.
 *
 * Generated by scripts/icons/build-icons.ts. Do not edit by hand.
 */

/** What every CIO glyph accepts, which is the shape a Lucide glyph accepts too. */
export interface CioGlyphProps {
  /** Square edge in pixels. */
  size?: number
  /** The weight the call site asks for, in a 24 box. */
  strokeWidth?: number
  class?: string
}

/** The weight call sites pass, and the weight the fit math is anchored to. */
const REFERENCE_STROKE = 1.8

/** The weight the set is drawn at in the 24 box: a notch firmer than Lucide. */
const DRAWN_STROKE = 1.9

/**
 * The pre-transform stroke a fitted group carries, so the glyph lands on the
 * drawn weight at whatever weight the call site passes.
 */
export function cioStrokeWidth(requested: number, fitScale: number): number {
  return (requested / REFERENCE_STROKE) * (DRAWN_STROKE / fitScale)
}
